style.css:
@-moz-document domain("fanfiction.net"), domain("m.fanfiction.net"), domain("fictionpress.com"), domain("m.fictionpress.com") {
/* Palette */
  :root {
    color-scheme: dark;
    --ff-bg: #14181d;
    --ff-surface: #1c2128;
    --ff-surface-2: #1a1f26;
    --ff-header: #0d1117;
    --ff-border: #262c33;
    --ff-border-2: #2d333b;
    --ff-text: #e6edf3;
    --ff-body: #c4cdd6;
    --ff-muted: #9aa5b1;
    --ff-link: #5fb0e6;
    --ff-link-hover: #9bd4ff;
    --ff-green: #3fb950;
    /* FFN navy lifted to a readable blue-slate; FP maroon handled below */
    --ff-brand: #243b66;
  }

  /* Base */
  html, body {
    background: var(--ff-bg) !important;
    color: var(--ff-body) !important;
  }

  /* Soften every light border into a subtle dark line */
  * {
    border-color: var(--ff-border) !important;
  }

  /* .caret is a CSS triangle — three border sides must stay transparent under the blanket
     reset above */
  .caret {
    border-top-color: var(--ff-muted) !important;
    border-right-color: transparent !important;
    border-bottom-color: transparent !important;
    border-left-color: transparent !important;
  }
  /* the story-actions menu opens upward: its triangle is drawn on border-bottom */
  .dropup .caret,
  .navbar-fixed-bottom .dropdown .caret {
    border-top-color: transparent !important;
    border-bottom-color: var(--ff-muted) !important;
  }

  /* title underline is a border-bottom, not text-decoration */
  .stitle,
  .novtitle {
    border-bottom-color: var(--ff-link) !important;
  }
  /* `a:hover` sets text-decoration:none, so this border IS the site's hover affordance */
  a:hover,
  .underline {
    border-bottom-color: var(--ff-link) !important;
  }
  /* the site's own `.nav-tabs > li > a:hover` outranks global a:hover — a hovered tab must
     not take the link accent */
  .nav-tabs > li > a:hover {
    border-bottom-color: var(--ff-border) !important;
  }

  /* Divider rules */
  /* <hr> is border-style:none over a gradient background, out of the border reset's reach */
  hr {
    background-color: var(--ff-border-2) !important;
    background-image: none !important;
  }
  /* `*` never matches pseudo-elements, so this border-top survives the blanket reset */
  .lc-wrapper::after {
    border-top-color: var(--ff-border-2) !important;
  }
  /* opaque pills masking the rule behind heading text */
  .lc-left,
  .lc-right {
    background-color: var(--ff-surface) !important;
  }
  /* Bootstrap separator inside the nav dropdowns */
  .dropdown-menu .divider {
    background-color: var(--ff-border-2) !important;
  }

  /* Main content surfaces */
  #content_wrapper,
  #content_wrapper_inner,
  #content_parent,
  .zui,
  /* five identically-painted classes from a per-page inline <style>; all five must be
     listed */
  .panel_normal,
  .panel_warning,
  .panel_error,
  .panel_success,
  .panel_plain,
  .lc,
  .lc-wrapper,
  .lc-lg,
  .lc-md,
  .lc-sm,
  .gui_normal,
  .gui_table,
  .goog-rtopics,
  .table-striped,
  .zmenu {
    background-color: var(--ff-surface) !important;
    color: var(--ff-body) !important;
  }

  #content_wrapper {
    box-shadow: none !important;
  }

  /* keep nested transparent wrappers transparent so we don't stack surfaces */
  .lc-wrapper,
  #content_wrapper_inner,
  #content_parent {
    background-color: transparent !important;
  }
  /* the reader's texture picker writes an inline background-IMAGE url() here (replayed for
     guests from xcookie2); a transparent background-COLOR cannot clear it */
  #content_wrapper_inner {
    background-image: none !important;
  }
  /* the picker's preview pane takes the same inline texture url() on click */
  #_fontastic_reading_preview {
    background-image: none !important;
    background-color: var(--ff-surface-2) !important;
  }

  /* the "Narrow Results" rail is a classless, idless <div>; its inline
     `background-color:#ffffff` is the only hook, and nothing else on FFN writes that literal */
  div[style*="background-color:#ffffff"] {
    background-color: var(--ff-surface) !important;
  }

  /* Header / top brand bar */
  /* the `div` qualifier is load-bearing: on the m. hosts the id sits on <body id="top"> */
  div#top {
    background-color: var(--ff-header) !important;
    border-bottom: 1px solid var(--ff-border-2) !important;
  }
  /* the bar's paint is a gradient background-IMAGE over a transparent bg-color */
  .t_head {
    background-image: none !important;
    background-color: var(--ff-header) !important;
    border-bottom: 1px solid var(--ff-border-2) !important;
  }
  /* header chrome, not links. The wordmark is `<a style="color:black"><b>` — name the `b`
     or the `a b` rule below outranks it. */
  .t_head a,
  .t_head a b {
    color: var(--ff-text) !important;
  }
  .t_head a:hover,
  .t_head a:hover b {
    color: var(--ff-link-hover) !important;
  }
  div#top a,
  div#top .icon-fictionpress,
  #name_login,
  #name_login a {
    color: var(--ff-text) !important;
  }
  /* Login / Sign Up pills in the header keep an accent so they stand out */
  div#top .btn,
  #name_login .btn {
    background-color: var(--ff-brand) !important;
    color: var(--ff-text) !important;
    border-color: var(--ff-border-2) !important;
  }
  div#top .btn:hover,
  #name_login .btn:hover {
    background-color: #2d4a80 !important;
  }

  /* Navigation menus / dropdowns */
  #nav_internal,
  #nav_internal a,
  .menulink,
  .xmenu_item,
  .dropdown,
  .dropdown > a,
  .dropdown-toggle {
    color: var(--ff-text) !important;
  }

  .dropdown-menu,
  ul.dropdown-menu,
  .open > .dropdown-menu {
    background-color: var(--ff-surface) !important;
    border: 1px solid var(--ff-border-2) !important;
    box-shadow: 0 6px 18px rgba(0,0,0,.5) !important;
  }
  .dropdown-menu li > a,
  .dropdown-menu a {
    color: var(--ff-body) !important;
  }
  /* Bootstrap 2's highlight is a background-IMAGE gradient over its background-color */
  .dropdown-menu li > a:hover,
  .dropdown-menu a:hover,
  .dropdown-menu > .active > a {
    background-color: var(--ff-brand) !important;
    background-image: none !important;
    color: var(--ff-text) !important;
  }
  /* dropdown group headings are `li.disabled > a`: dimmed and hover-less is the only cue
     they are not links */
  .dropdown-menu > .disabled > a,
  .dropdown-menu > .disabled > a:hover,
  .dropdown-menu > .disabled > a:focus {
    color: var(--ff-muted) !important;
    background-color: transparent !important;
    background-image: none !important;
  }

  /* sub-nav grey links (Stories / Crossovers / All / Specific) */
  .menulink,
  #content_wrapper a[style*="color:#999"],
  .menulink a {
    color: var(--ff-muted) !important;
  }

  /* Links */
  a {
    color: var(--ff-link) !important;
  }
  a:hover {
    color: var(--ff-link-hover) !important;
  }
  /* keep header / nav links from inheriting the body link blue where set above */
  div#top a:hover {
    color: var(--ff-link-hover) !important;
  }

  /* .xcontrast_txt and `b` outrank the bare `a` above */
  a.xcontrast_txt,
  #profile_top a,
  #profile_top a.xcontrast_txt,
  a b,
  a strong {
    color: var(--ff-link) !important;
  }
  a.xcontrast_txt:hover,
  #profile_top a:hover,
  #profile_top a.xcontrast_txt:hover,
  a:hover b,
  a:hover strong {
    color: var(--ff-link-hover) !important;
  }
  /* this row alone puts the entry LABEL inside the anchor's glyph span, where the blanket
     `span` rule below would strip it. Its `.icon-*` siblings carry inline `color:black`. */
  a span.icon-cr-warning {
    color: var(--ff-link) !important;
  }
  a:hover span.icon-cr-warning {
    color: var(--ff-link-hover) !important;
  }
  /* these blocks end in bare `<span data-xutime>` dates that only inherit the block grey,
     which the direct `span { color }` declaration below would light. Must stay ABOVE the
     `span._thread` / brand-glyph rules — they tie it and win only on order. */
  .xgray span,
  .gray span,
  .z-list .z-padtop2 span {
    color: var(--ff-muted) !important;
  }

  /* a plain <span> wraps the glyph <span>, so the body-text rule below greys both */
  span._thread,
  span._thread span {
    color: var(--ff-link) !important;
  }
  span._thread:hover,
  span._thread:hover span {
    color: var(--ff-link-hover) !important;
  }
  /* orange is the only cue this leads to the review list, not the story; #f50 clears 4.5:1.
     `.z-list a` below ties `a.reviews`, so the row form needs the `.z-list` prefix. */
  a.reviews,
  a.reviews:hover,
  .reviews,
  .z-list a.reviews,
  .z-list a.reviews:hover {
    color: #ff5500 !important;
  }

  /* the inline brand hue loses to the blanket `span` rule below; the crossover blue is
     lifted off 2:1 */
  span.icon-rss-squared {
    color: #ff8f00 !important;
  }
  span.icon-shuffle {
    color: #6d86f0 !important;
  }
  /* the blanket `span` rule promotes both to full ink, but FFN keeps them a step under body
     copy and their source values are unreadable on dark */
  span.xicon-section-arrow,
  span.icon-twitter-3 {
    color: var(--ff-muted) !important;
  }

  /* Headings & general text */
  h1, h2, h3, h4, h5, h6, b, strong {
    color: var(--ff-text) !important;
  }
  .xcontrast_txt,
  .xgray,
  td, th, p, span, div, li, label, dt, dd {
    color: var(--ff-body) !important;
  }
  .xgray, .gray, small {
    color: var(--ff-muted) !important;
  }
  /* as a direct div child, `small` is the "Narrow Results" heading and the header separator
     pipe — the strongest ink there natively */
  div > small {
    color: var(--ff-body) !important;
  }
  /* FFN's inline fine-print greys, which the blanket text rule above outranks.
     Keep a literal `;` OUT of these selectors: parse-check.js finds a rule's prelude by
     scanning back to the previous `;` and reports a valid rule as dead.
     An anchor matches only when it carries the grey itself; one inside a greyed block keeps the
     link accent. Placed after the `a:hover` arm so a grey anchor stays grey under the cursor —
     its hover cue is the underline. */
  div[style*="color:gray"],
  span[style*="color:gray"],
  a[style*="color:gray"],
  span[style*="color:#8c8c8c"],
  div[style*="color:#c4c4c4"] {
    color: var(--ff-muted) !important;
  }

  /* Story list rows (browse / search results) */
  .z-list,
  .z-list-content {
    background-color: var(--ff-surface) !important;
    border-bottom: 1px solid var(--ff-border) !important;
  }
  .z-list:hover {
    background-color: var(--ff-surface-2) !important;
  }
  .z-list a,
  .z-list .stitle {
    color: var(--ff-link) !important;
  }
  /* the metadata line sits a step under the summary — the site's only ranking of the two;
     muted keeps the step and clears 6.4:1 */
  .z-list .xgray,
  .z-list .z-padtop2 {
    color: var(--ff-muted) !important;
  }

  /* Story reader (#storytext) */
  /* the m. hosts' contrast toggle writes the pick onto this column as an inline
     background-color, replayed on reload by a document.write'd sheet on `.storycontent` */
  #storytext,
  #storytextp,
  .storytext,
  #storycontent,
  .storycontent {
    color: var(--ff-body) !important;
    background-color: transparent !important;
  }
  /* do NOT force one colour on inner runs — author bold/italic/alignment must survive; only
     normalize the black default */
  #storytext p,
  #storytext div,
  #storytext span[style*="color: rgb(0, 0, 0)"],
  #storytext font[color="#000000"],
  #storytext font[color="black"] {
    color: var(--ff-body) !important;
  }
  #storytext hr {
    border-color: var(--ff-border-2) !important;
  }

  /* story info box on the chapter page */
  #profile_top {
    background-color: var(--ff-surface) !important;
    border: 1px solid var(--ff-border) !important;
    color: var(--ff-body) !important;
  }
  #profile_top b,
  #profile_top .xcontrast_txt {
    color: var(--ff-text) !important;
  }
  /* the rule above matches this on `.xcontrast_txt`, which would invert its step below the
     summary */
  #profile_top .xgray.xcontrast_txt,
  #profile_top .xgray {
    color: var(--ff-muted) !important;
  }

  /* Reading-options bar + chapter select */
  select,
  select[name="chapter"],
  #chap_select {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
    border: 1px solid var(--ff-border-2) !important;
  }
  select option {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
  }
  /* `<select size="7">` rows are always visible, so the highlight on the picked one is the
     only cue a filter was set */
  select[size] option:checked {
    background-color: var(--ff-brand) !important;
    color: var(--ff-text) !important;
  }
  /* `.selection_hl` is the only "this filter is active" cue, and the generic select rule and
     border reset outrank it */
  select.selection_hl {
    background-color: rgba(63, 185, 80, .18) !important;
    border-color: var(--ff-green) !important;
    color: var(--ff-text) !important;
  }

  /* Buttons / segmented controls / sort tabs */
  button,
  .btn,
  input[type="button"],
  input[type="submit"],
  input[type="reset"] {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
    border: 1px solid var(--ff-border-2) !important;
    background-image: none !important;
    text-shadow: none !important;
  }
  button:hover,
  .btn:hover {
    background-color: #232a32 !important;
    color: var(--ff-text) !important;
  }
  /* the flat fill Bootstrap gives an OPEN toggle is the only pressed cue on the button, and
     the `.btn` fill above is !important */
  .btn-group.open .btn.dropdown-toggle {
    background-color: #232a32 !important;
  }
  .btn.active,
  .btn-primary,
  .active > .btn {
    background-color: var(--ff-brand) !important;
    color: var(--ff-text) !important;
  }
  /* the only primary CTA shipped logged-out; the generic `.btn:hover` above ties this, so
     this arm must stay AFTER it */
  .btn-primary:hover,
  .btn-primary:focus,
  .btn-primary:active {
    background-color: #2d4a80 !important;
  }
  /* the !important rules above would repaint a disabled control at full strength. Must stay
     AFTER the hover/active arms — it ties them and wins on order. `.btn:hover` (0,2,0)
     outranks `button[disabled]` (0,1,1), so the `:hover` forms are needed. */
  button[disabled],
  button[disabled]:hover,
  input[disabled],
  input[disabled]:hover,
  select[disabled],
  textarea[disabled],
  .btn[disabled],
  .btn[disabled]:hover,
  .btn.disabled,
  .btn.disabled:hover {
    background-color: var(--ff-bg) !important;
    color: var(--ff-muted) !important;
    border-color: var(--ff-border) !important;
    opacity: .7 !important;
  }

  /* Form inputs & search */
  input[type="text"],
  input[type="search"],
  input[type="email"],
  input[type="password"],
  input:not([type]),
  textarea {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
    border: 1px solid var(--ff-border-2) !important;
  }
  ::placeholder {
    color: var(--ff-muted) !important;
    opacity: 1 !important;
  }
  /* the field rule above is !important and holds border and ink neutral while the site's
     pink box-shadow lands, so all three must be restated */
  input:focus:invalid,
  textarea:focus:invalid,
  select:focus:invalid {
    border-color: #f85149 !important;
    color: #f85149 !important;
    box-shadow: 0 0 6px rgba(248, 81, 73, .45) !important;
  }
  /* the reCAPTCHA panel is cross-origin, so inverting the frame is the only lever; the
     hue-rotate restores the brand blue and green tick. `api2/anchor` only — `api2/bframe` is
     the photo-grid challenge and must not be inverted. */
  iframe[src*="recaptcha/api2/anchor"] {
    filter: invert(.92) hue-rotate(180deg) !important;
  }

  /* Tables */
  /* the <td> carry their own light bg; target the cells, not just the rows */
  .gui_table,
  .gui_table td,
  .gui_table th,
  .tcat,
  table.table,
  table.table td,
  table.table th,
  .table-striped td,
  .table-striped th,
  .table-striped > tbody > tr:nth-of-type(odd) > td,
  .table-bordered {
    background-color: var(--ff-surface) !important;
    color: var(--ff-body) !important;
    border-color: var(--ff-border) !important;
  }
  .tcat,
  thead th {
    background-color: var(--ff-header) !important;
    color: var(--ff-text) !important;
  }
  /* `.thead` is dimmed by the site — the only thing reading the row as a header — and
     `table.table th` above outranks it */
  table.table th.thead,
  th.thead {
    color: var(--ff-muted) !important;
  }
  .table-striped > tbody > tr:nth-of-type(even) > td {
    background-color: var(--ff-surface-2) !important;
  }
  tr:hover > td {
    background-color: var(--ff-surface-2) !important;
  }

  /* Forum post quotes */
  /* an unclassed blockquote inherits the post ink, so only the bar needs the line colour */
  blockquote {
    color: var(--ff-body) !important;
    border-color: var(--ff-border-2) !important;
  }
  /* the quote wrapper sits a step UNDER the post copy; its 5px bar is only ~1.2:1 on dark,
     so the ink step carries the block. Inner runs must be listed — the blanket p/div/span rule
     beats inheritance. Anchors stay out. */
  .quoteStyle,
  .quoteStyle p,
  .quoteStyle div,
  .quoteStyle span,
  .quoteStyle li,
  .quoteStyle b,
  .quoteStyle strong,
  .quoteStyle em {
    color: var(--ff-muted) !important;
  }
  .quoteStyle {
    border-color: var(--ff-border-2) !important;
  }

  /* Highlight spans (.hiliteStyle) */
  /* pale-green mark on "(N posts)" counts and matched search terms */
  .hiliteStyle {
    background-color: rgba(63, 185, 80, .2) !important;
    color: var(--ff-text) !important;
  }

  /* Badges / counters */
  /* default grey badge → dark chip with readable light text */
  .badge {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
    border: 1px solid var(--ff-border-2) !important;
    text-shadow: none !important;
  }
  /* `.badge-blue` has no site rule and renders as the plain `.badge`; giving it a fill would
     clash with the selected topic-filter chip */
  /* the site's `.badge-active` / `.badge:hover` carry no !important, so the generic `.badge`
     rule above outranks them */
  .badge:hover {
    background-color: #232a32 !important;
  }
  .badge-active,
  .badge-active:hover {
    background-color: var(--ff-brand) !important;
    border-color: var(--ff-brand) !important;
    color: var(--ff-text) !important;
  }

  /* the light-grey join-date pill beside every beta reader / community member */
  .xcount {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-muted) !important;
    border: 1px solid var(--ff-border-2) !important;
  }
  .xcount:hover {
    background-color: #232a32 !important;
    color: var(--ff-text) !important;
  }

  /* Profile / story tabs (.nav-tabs) */
  /* Selection lives on `li.active` ONLY: `a.current` is an inert marker the site never styles
     or moves */
  .nav-tabs > li > a,
  .nav-tabs a {
    background-color: transparent !important;
    color: var(--ff-link) !important;
  }
  /* only the selected tab draws the folder outline natively, and that is the whole cue since
     the active fill matches the panel; the blanket border reset boxes up every tab */
  .nav-tabs > li > a {
    border-color: transparent !important;
  }
  .nav-tabs > li.active > a,
  .nav-tabs > .active > a:hover,
  .nav-tabs > .active > a:focus {
    background-color: var(--ff-surface) !important;
    color: var(--ff-text) !important;
    border-color: var(--ff-border-2) !important;
    border-bottom-color: var(--ff-surface) !important;
  }
  /* native hover restores an outline, so the hovered tab must box up again; bottom stays the
     line colour, not the link accent */
  .nav-tabs > li > a:hover {
    background-color: var(--ff-surface-2) !important;
    border-color: var(--ff-border-2) var(--ff-border-2) var(--ff-border) !important;
  }

  /* Advanced-filter modal */
  .modal,
  .modal-body,
  .modal-header,
  .modal-footer,
  .modal-content,
  #filters {
    background-color: var(--ff-surface) !important;
    color: var(--ff-body) !important;
    border-color: var(--ff-border-2) !important;
  }
  /* a white inset box-shadow highlight runs along the footer's top edge */
  .modal-footer,
  .modal-header {
    box-shadow: none !important;
  }

  /* Semantic status colours */
  /* FFN's dark greens vanish on dark; lift to the palette green, keeping the semantic */
  span[style*="color:green"],
  span[style*="#04761c"],
  span[style*="#080"],
  .status_complete,
  font[color="green"] {
    color: var(--ff-green) !important;
  }
  /* red "Without" pairs with green "Plus" to mark exclude vs include; the blanket span rule
     flattens it, and #c00000 is only ~2.8:1 here */
  span[style*="#c00000"],
  span[style*="color:red"],
  font[color="red"] {
    color: #f85149 !important;
  }

  /* each status class wraps its text in a `<span>` the blanket text rule outranks; the `b`
     arm is not redundant, since the message words sit in `<b>`. `red` and `green` miss AA on
     the panel surface and take palette equivalents; the orange stays verbatim. */
  .gui_error,
  .gui_error b,
  .gui_error strong {
    color: #f85149 !important;
  }
  .gui_warning,
  .gui_warning b,
  .gui_warning strong {
    color: #e56717 !important;
  }
  .gui_success,
  .gui_success b,
  .gui_success strong {
    color: var(--ff-green) !important;
  }

  /* Cookie bar */
  /* the Accept control's only affordance is an inline `border:1px whitesmoke solid`, which
     the blanket reset drops below the bar's own #363636 */
  #cookie_notice div[onclick] {
    border-color: var(--ff-muted) !important;
  }

  /* Footer */
  #footer,
  .footer,
  #zfooter {
    background-color: var(--ff-header) !important;
    color: var(--ff-muted) !important;
    border-top: 1px solid var(--ff-border-2) !important;
  }
  #footer a, .footer a { color: var(--ff-link) !important; }

  /* Ad slots */
  ins.adsbygoogle,
  .adsbygoogle,
  div[id^="div-gpt-ad"],
  div[id*="_ad_"],
  div[id^="ad_"],
  .ad_slot,
  [id^="google_ads"],
  iframe[id^="google_ads"],
  iframe[id^="aswift"],
  .goog-rtopics,
  .goog-rentries,
  .goog-rentry,
  .google-anno,
  .google-anno-skip,
  .google-anno-sc {
    background-color: var(--ff-bg) !important;
  }

  /* Misc: don't tint cover images */
  img, .cimage {
    background-color: transparent !important;
  }
  /* keyed to the one placeholder filename — real cover art and avatars come from
     /image/<id>/ and must stay untouched */
  img[src*="d_60_90"] {
    filter: brightness(.35) !important;
  }
  /* a third of this raster's opaque pixels are pure white (the paper); invert makes it the
     row surface, hue-rotate restores the outline hue. The other fcons/ficons rasters are line
     art with no white plate (measured) — do not filter them. */
  img[src*="fcons/script-"] {
    filter: invert(1) hue-rotate(180deg) !important;
  }
}
